import assert from 'node:assert/strict';
import type {Block} from '../../src/core/types';
import type {GeneratedBody} from '../../src/core/generators/definition';
import facts from './legacy-2019-autumn-structures-facts.json';
const para=(b:Block)=>{assert.equal(b.type,'paragraph');return(b as Extract<Block,{type:'paragraph'}>).text;};
function diagram(b:Block,profile:string,values:number[]){assert.equal(b.type,'diagram');if(b.type!=='diagram')throw Error('diagram');assert.equal(b.scene.kind,'source_figure');if(b.scene.kind!=='source_figure')throw Error('scene');assert.equal(b.scene.profile,profile);assert.deepEqual(b.scene.values,values);assert(b.alt&&b.alt.length>25);return b;}
export function legacy2019StructuresAllPaths(d:Record<string,number>){
 // Independent Boolean connection matrix and edge labels, rather than the
 // production's four direct arithmetic expressions.
 const edge=[['A',0,1],['B',0,2],['C',1,2],['D',1,4],['E',2,3],['F',3,5],['G',4,5],['dummy',3,4]] as const,result:{path:string[];days:number}[]=[];
 const visit=(n:number,path:string[],days:number)=>{if(n===5){result.push({path,days});return;}for(const [name,from,to]of edge)if(from===n)visit(to,[...path,name],days+(name==='dummy'?0:d[name]));};visit(0,[],0);return result;
}
export function legacy2019StructuresHttpTruth(v:number){const plan=facts.results.am34[v],port=plan.port,assignment=[80,8080,49152,65535];return plan.choices.map(packets=>assignment.every(ap=>assignment.every(bp=>packets.every(p=>({AB_request:8080,BC_request:80,BA_response:ap,CB_response:bp})[p]===port))));}
export function assertLegacy2019AutumnStructures(source:string,b:GeneratedBody,v:number[]){
 const n=Number(source.split('-').at(-1));assert([3,5,7,34,45,52].includes(n));assert.equal(b.choices.length,4);assert.equal(b.answerParts,undefined);const explanation=b.explanation;assert(explanation.length>150);assert(!/[アイウエ]の選択肢|選択肢は順に|左から順|転載|生成条件|編集方針/.test(explanation));
 const truth:boolean[]=[];
 if(n===3){const expected=facts.results.am3[v[0]];assert.equal(b.prompt.length,2);const stem=para(b.prompt[0]);for(const s of['無向グラフ','隣接行列','行と列','存在する場合は1','存在しない場合は0'])assert(stem.includes(s));diagram(b.prompt[1],'legacy-2019-adjacency-matrix',v);
  for(let c=0;c<4;c++){assert.equal(b.choices[c].length,1);diagram(b.choices[c][0],'legacy-2019-adjacency-graph',[v[0],c]);truth.push(JSON.stringify(expected.choiceEdges[c])===JSON.stringify(expected.edgeSet));}
  assert(explanation.includes(`この条件の辺は${expected.edgeSet.map(e=>`${e[0]}―${e[1]}`).join('、')}の${expected.edges}本である。`));for(const s of['無向','二重には数えない','過不足なく一致','一本欠いて','余分な一本','ラベル','途中のノード'])assert(explanation.includes(s));
 }else if(n===5){const mu=60+10*v[0],sd=10+2*v[1],expected=facts.results.am5.find(r=>r.values[0]===mu&&r.values[1]===sd);assert(expected);assert.equal(para(b.prompt[0]),`平均が${mu}、標準偏差が${sd}の正規分布を表すグラフはどれか。`);assert.equal(b.prompt.length,1);for(let c=0;c<4;c++){assert.equal(b.choices[c].length,1);diagram(b.choices[c][0],'legacy-2019-density-plot',[...v,c]);truth.push(expected.truth[c]);}for(const s of[`平均${mu}`,`標準偏差${sd}`,`${mu+sd}`,`${sd/2}`,'左右対称','変曲点','二つの山','左の裾','正規分布の形ではない'])assert(explanation.includes(s));
 }else if(n===7){assert.equal(b.prompt.length,2);assert.equal(para(b.prompt[0]),'次のBNFで定義される＜変数名＞に合致するものはどれか。');diagram(b.prompt[1],'legacy-2019-bnf-rules',v);
  const words=b.choices.map(cs=>{assert.equal(cs.length,1);return para(cs[0]);});assert.deepEqual(words,facts.results.am7[v[0]].choices);for(const word of words)truth.push(/^[A-F0-9_]+$/.test(word)&&/^[A-F]$/.test(word[v[0]===0?0:word.length-1]));for(const s of[v[0]===0?'右側':'左側',v[0]===0?'先頭':'末尾','A〜F','0〜9','導出','他のプログラム言語'])assert(explanation.includes(s));for(const word of words)assert(explanation.includes(word));
 }else if(n===34){const expected=facts.results.am34[v[0]],stem=para(b.prompt[0]);assert.equal(stem,`クライアントAがポート番号8080のHTTPプロキシサーバBを経由してポート番号80のWebサーバCにアクセスしているとき、宛先ポート番号が常に${expected.port}になるTCPパケットはどれか。`);assert.equal(b.prompt.length,1);
  const names:Record<string,string>={AB_request:'AからBへのHTTP要求',BC_request:'BからCへのHTTP要求',BA_response:'BからAへのHTTP応答',CB_response:'CからBへのHTTP応答'};for(let c=0;c<4;c++){assert.equal(b.choices[c].length,1);assert.equal(para(b.choices[c][0]),expected.choices[c].map(p=>names[p]).join('及び')+(expected.choices[c].length===1?'だけ':''));}truth.push(...legacy2019StructuresHttpTruth(v[0]));for(const s of['別々のTCP接続','待受ポート8080','待受ポート80',`常に${expected.port}`,'偶然','常に等しいとはいえない','全て'])assert(explanation.includes(s));assert(!/絶対|応答.*ならない/.test(explanation));assert(explanation.includes(v[0]===0?'AからBへのHTTP要求だけ':'BからCへのHTTP要求だけ'));
 }else if(n===45){assert.equal(b.prompt.length,2);const target=['○','二本の平行線','矢印'][v[0]];assert.equal(para(b.prompt[0]),`図は、構造化分析法で用いられるDFDの例である。図中の“${target}”が表しているものはどれか。`);const f=diagram(b.prompt[1],'legacy-2019-dfd-symbols',[0]);assert(!/プロセス|アクティビティ|データストア|データフロー/.test(f.alt!),'Answer concepts must not leak through alt');assert.deepEqual(b.choices.map(c=>para(c[0])),['アクティビティ','データストア','データフロー','プロセス']);truth.push(...facts.results.am45[v[0]].truth);assert(explanation.startsWith(['本図のDFDの記法では、丸はデータを入力して加工し出力するプロセスを表す。','本図のDFDの記法では、二本の平行線はデータを保存するデータストアを表す。','本図のDFDの記法では、矢印はデータの移動と向きを表すデータフローである。'][v[0]]));for(const s of['本図のDFDの記法', ['プロセス','データストア','データフロー'][v[0]],'形式上の名称','一般語','全面的に排他的','別種の図'])assert(explanation.includes(s));
 }else if(n===52){const expected=facts.results.am52[v[0]];assert.equal(b.prompt.length,2);assert.equal(para(b.prompt[0]),'あるプロジェクトの日程計画をアローダイアグラムで示す。クリティカルパスはどれか。');diagram(b.prompt[1],'legacy-2019-critical-network',v);const options=b.choices.map(c=>para(c[0]));assert.deepEqual(options,['A，C，E，F','A，D，G','B，E，F','B，E，G']);const paths=legacy2019StructuresAllPaths(expected.durations);assert.equal(paths.length,5);const longest=Math.max(...paths.map(p=>p.days));assert.equal(paths.filter(p=>p.days===longest).length,1);const actual=paths.find(p=>p.days===longest)!.path.filter(s=>s!=='dummy').join(',');truth.push(...options.map(s=>s.replaceAll('，',',')===actual));assert.equal(longest,expected.max);for(const p of paths){const names=p.path.filter(s=>s!=='dummy');assert(explanation.includes(`${names.map(s=>expected.durations[s as keyof typeof expected.durations]).join('+')}=${p.days}日`));}for(const s of['候補にないA→C→E→ダミー→G','所要日数を加算しない',`最長の${longest}日`,'一意のクリティカルパス','全ての先行作業'])assert(explanation.includes(s));assert(explanation.includes(['A→C→E→F','A→D→G','B→E→F','B→E→ダミー→G'][truth.indexOf(true)]));
 }
 assert.equal(truth.filter(Boolean).length,1);assert.equal(b.correctIndex,truth.indexOf(true));return truth;
}
